import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  Modal,
  TouchableOpacity,
  ScrollView,
  TextInput,
  Alert,
  SafeAreaView,
  FlatList,
  Platform,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import DateTimePicker from '@react-native-community/datetimepicker';

const EditWorkoutModal = ({ 
  visible, 
  workout, 
  onSave, 
  onCancel 
}) => {
  const [editedWorkout, setEditedWorkout] = useState(null);
  const [notes, setNotes] = useState('');
  const [rating, setRating] = useState(5);
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [duration, setDuration] = useState(0);
  const [exercises, setExercises] = useState([]);
  const [showDatePicker, setShowDatePicker] = useState(false);

  useEffect(() => {
    if (workout) {
      console.log('EditWorkoutModal - useEffect - workout:', workout);
      setEditedWorkout({ ...workout });
      setNotes(workout.notes || '');
      setRating(workout.ratings?.workoutRating || 5);
      const workoutDate = new Date(workout.startTime);
      console.log('EditWorkoutModal - Setting selectedDate from workout:', workoutDate);
      setSelectedDate(workoutDate);
      
      setExercises(workout.exercises || []);
      
      // Calculate duration in minutes
      const startTime = new Date(workout.startTime);
      const endTime = new Date(workout.endTime);
      const durationMinutes = Math.round((endTime - startTime) / 1000 / 60);
      setDuration(durationMinutes);
    }
  }, [workout]);

  const handleSave = () => {
    if (!editedWorkout) return;

    console.log('EditWorkoutModal - handleSave - selectedDate:', selectedDate);
    console.log('EditWorkoutModal - handleSave - duration:', duration);

    // Create workoutDate in local timezone to avoid timezone issues
    const workoutDate = `${selectedDate.getFullYear()}-${String(selectedDate.getMonth() + 1).padStart(2, '0')}-${String(selectedDate.getDate()).padStart(2, '0')}`;
    
    console.log('EditWorkoutModal - handleSave - workoutDate (local):', workoutDate);
    
    // Keep the original start and end times, just update the workoutDate
    const updatedWorkout = {
      ...editedWorkout,
      workoutDate: workoutDate, // Use local date to avoid timezone issues
      exercises: exercises,
      notes: notes.trim(),
      ratings: {
        ...editedWorkout.ratings,
        workoutRating: rating
      },
      lastModified: new Date().toISOString(),
    };

    console.log('EditWorkoutModal - handleSave - updatedWorkout:', updatedWorkout);
    onSave(updatedWorkout);
  };

  const handleCancel = () => {
    setNotes('');
    setRating(5);
    setSelectedDate(new Date());
    setDuration(0);
    setExercises([]);
    onCancel();
  };

  const addExercise = () => {
    const newExercise = {
      id: Date.now(),
      name: '',
      sets: [{
        id: Date.now(),
        reps: '',
        weight: '',
        completed: false,
      }],
      notes: '',
      order: exercises.length,
    };
    setExercises([...exercises, newExercise]);
  };

  const removeExercise = (exerciseId) => {
    Alert.alert(
      'Remove Exercise',
      'Are you sure you want to remove this exercise?',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Remove',
          style: 'destructive',
          onPress: () => {
            setExercises(prev => prev.filter(ex => ex.id !== exerciseId));
          }
        }
      ]
    );
  };

  const updateExercise = (exerciseId, field, value) => {
    setExercises(prev => prev.map(exercise => {
      if (exercise.id === exerciseId) {
        return { ...exercise, [field]: value };
      }
      return exercise;
    }));
  };

  const addSet = (exerciseId) => {
    setExercises(prev => prev.map(exercise => {
      if (exercise.id === exerciseId) {
        const newSet = {
          id: Date.now(),
          reps: '',
          weight: '',
          completed: false,
        };
        return {
          ...exercise,
          sets: [...exercise.sets, newSet],
        };
      }
      return exercise;
    }));
  };

  const removeSet = (exerciseId, setId) => {
    setExercises(prev => prev.map(exercise => {
      if (exercise.id === exerciseId) {
        const updatedSets = exercise.sets.filter(set => set.id !== setId);
        return { ...exercise, sets: updatedSets };
      }
      return exercise;
    }));
  };

  const updateSet = (exerciseId, setId, field, value) => {
    setExercises(prev => prev.map(exercise => {
      if (exercise.id === exerciseId) {
        const updatedSets = exercise.sets.map(set => {
          if (set.id === setId) {
            const parsedValue = value === '' ? '' : parseInt(value) || 0;
            return { ...set, [field]: parsedValue };
          }
          return set;
        });
        return { ...exercise, sets: updatedSets };
      }
      return exercise;
    }));
  };

  const renderRatingStars = () => {
    const stars = [];
    for (let i = 1; i <= 10; i++) {
      stars.push(
        <TouchableOpacity
          key={i}
          onPress={() => setRating(i)}
          style={styles.starContainer}
        >
          <Ionicons
            name={i <= rating ? 'star' : 'star-outline'}
            size={24}
            color={i <= rating ? '#FFD700' : '#ccc'}
          />
        </TouchableOpacity>
      );
    }
    return stars;
  };

  const getRatingText = (rating) => {
    if (rating >= 9) return 'Excellent';
    if (rating >= 7) return 'Great';
    if (rating >= 5) return 'Good';
    if (rating >= 3) return 'Poor';
    return 'Terrible';
  };

  const renderExercise = ({ item: exercise }) => (
    <View style={styles.exerciseContainer}>
      <View style={styles.exerciseHeader}>
        <TextInput
          style={styles.exerciseNameInput}
          value={exercise.name}
          onChangeText={(text) => updateExercise(exercise.id, 'name', text)}
          placeholder="Exercise name"
        />
        <TouchableOpacity
          onPress={() => removeExercise(exercise.id)}
          style={styles.removeButton}
        >
          <Ionicons name="trash-outline" size={20} color="#FF3B30" />
        </TouchableOpacity>
      </View>

      {exercise.sets.map((set, setIndex) => (
        <View key={set.id} style={styles.setRow}>
          <Text style={styles.setLabel}>Set {setIndex + 1}</Text>
          <TextInput
            style={styles.setInput}
            value={set.weight.toString()}
            onChangeText={(text) => updateSet(exercise.id, set.id, 'weight', text)}
            placeholder="Weight"
            keyboardType="numeric"
          />
          <TextInput
            style={styles.setInput}
            value={set.reps.toString()}
            onChangeText={(text) => updateSet(exercise.id, set.id, 'reps', text)}
            placeholder="Reps"
            keyboardType="numeric"
          />
          <TouchableOpacity
            onPress={() => removeSet(exercise.id, set.id)}
            style={styles.removeSetButton}
          >
            <Ionicons name="close-circle-outline" size={16} color="#FF3B30" />
          </TouchableOpacity>
        </View>
      ))}

      <TouchableOpacity
        onPress={() => addSet(exercise.id)}
        style={styles.addSetButton}
      >
        <Ionicons name="add-circle-outline" size={20} color="#007AFF" />
        <Text style={styles.addSetText}>Add Set</Text>
      </TouchableOpacity>
    </View>
  );

  const handleDateChange = (event, selectedDate) => {
    console.log('EditWorkoutModal - handleDateChange called:', { event, selectedDate });
    setShowDatePicker(false);
    if (selectedDate) {
      console.log('EditWorkoutModal - Setting selectedDate to:', selectedDate);
      setSelectedDate(selectedDate);
    }
  };

  const handleWebDateChange = (event) => {
    const newDate = new Date(event.target.value);
    console.log('EditWorkoutModal - Web date change:', newDate);
    setSelectedDate(newDate);
  };

  if (!workout) return null;

  return (
    <Modal
      visible={visible}
      animationType="slide"
      presentationStyle="pageSheet"
    >
      <SafeAreaView style={styles.container}>
        <View style={styles.header}>
          <TouchableOpacity onPress={handleCancel} style={styles.cancelButton}>
            <Text style={styles.cancelButtonText}>Cancel</Text>
          </TouchableOpacity>
          <Text style={styles.headerTitle}>Edit Workout</Text>
          <TouchableOpacity onPress={handleSave} style={styles.saveButton}>
            <Text style={styles.saveButtonText}>Save</Text>
          </TouchableOpacity>
        </View>

        <ScrollView style={styles.content}>
          <View style={styles.section}>
            <Text style={styles.sectionTitle}>Workout Details</Text>
            
            <View style={styles.detailRow}>
              <Text style={styles.detailLabel}>Date:</Text>
              {Platform.OS === 'web' ? (
                <input
                  type="date"
                  value={selectedDate.toISOString().split('T')[0]}
                  onChange={handleWebDateChange}
                  style={{
                    padding: 8,
                    fontSize: 16,
                    borderWidth: 1,
                    borderColor: '#e0e0e0',
                    borderRadius: 8,
                    backgroundColor: '#f0f0f0',
                    color: '#333',
                    fontWeight: '600',
                  }}
                />
              ) : (
                <TouchableOpacity
                  onPress={() => {
                    setShowDatePicker(true);
                  }}
                  style={styles.dateButton}
                >
                  <Text style={styles.dateButtonText}>
                    {selectedDate.toLocaleDateString()}
                  </Text>
                  <Ionicons name="calendar-outline" size={20} color="#007AFF" />
                </TouchableOpacity>
              )}
            </View>

            <View style={styles.detailRow}>
              <Text style={styles.detailLabel}>Duration (minutes):</Text>
              <TextInput
                style={styles.durationInput}
                value={duration.toString()}
                onChangeText={(text) => setDuration(parseInt(text) || 0)}
                keyboardType="numeric"
                placeholder="0"
              />
            </View>
          </View>

          <View style={styles.section}>
            <View style={styles.sectionHeader}>
              <Text style={styles.sectionTitle}>Exercises</Text>
              <TouchableOpacity onPress={addExercise} style={styles.addExerciseButton}>
                <Ionicons name="add-circle-outline" size={24} color="#007AFF" />
              </TouchableOpacity>
            </View>
            
            <FlatList
              data={exercises}
              renderItem={renderExercise}
              keyExtractor={(item) => item.id.toString()}
              scrollEnabled={false}
            />
          </View>

          <View style={styles.section}>
            <Text style={styles.sectionTitle}>Rating</Text>
            <View style={styles.ratingContainer}>
              {renderRatingStars()}
            </View>
            <Text style={styles.ratingText}>{getRatingText(rating)}</Text>
          </View>

          <View style={styles.section}>
            <Text style={styles.sectionTitle}>Notes</Text>
            <TextInput
              style={styles.notesInput}
              value={notes}
              onChangeText={setNotes}
              placeholder="Add notes about this workout..."
              multiline
              numberOfLines={4}
              textAlignVertical="top"
            />
          </View>
        </ScrollView>

        {showDatePicker && Platform.OS !== 'web' && (
          <DateTimePicker
            value={selectedDate}
            mode="date"
            display={Platform.OS === 'ios' ? 'spinner' : 'default'}
            onChange={handleDateChange}
            style={{ backgroundColor: 'white' }}
          />
        )}
      </SafeAreaView>
    </Modal>
  );
};

